/**
 * 檔案資料夾共用：讓系統使用者可直接在雲端硬碟線上檢視（不寄通知信）
 *   督導紀錄檔案 → 有「督導紀錄檢視」者；督導改善檔案 → 有「行程檢視」者
 *   停用或失去權限的帳號，移除其檢視權（只處理 reader，不動擁有者與編輯者）
 */
function shareSync_() {
  const owner = String(prop_('OWNER_EMAIL', DEFAULT_OWNER)).toLowerCase();
  const users = readTable_('使用者').filter(u => u.啟用 === true || String(u.啟用).toUpperCase() === 'TRUE');
  const rep = {};
  [[djFolder_(), '督導紀錄檢視', '督導紀錄檔案'], [impFolder_(), '行程檢視', '督導改善檔案']].forEach(([fid, perm, label]) => {
    const want = {};
    users.forEach(u => { const e = String(u.Email).trim().toLowerCase(); if (e && e !== owner && permsOf_(u).indexOf(perm) >= 0) want[e] = 1; });
    const cur = JSON.parse(driveFetch_('https://www.googleapis.com/drive/v3/files/' + fid + '/permissions?fields=permissions(id,type,role,emailAddress)&supportsAllDrives=true').getContentText()).permissions || [];
    const have = {}; cur.forEach(p => { if (p.type === 'user' && p.emailAddress) have[p.emailAddress.toLowerCase()] = p; });
    const r = { 新增: [], 移除: [] };
    Object.keys(want).forEach(e => {
      if (have[e]) return;
      driveFetch_('https://www.googleapis.com/drive/v3/files/' + fid + '/permissions?sendNotificationEmail=false&supportsAllDrives=true', {
        method: 'post', contentType: 'application/json', payload: JSON.stringify({ type: 'user', role: 'reader', emailAddress: e }) });
      r.新增.push(e);
    });
    Object.keys(have).forEach(e => {
      const p = have[e]; if (want[e] || e === owner || p.role !== 'reader') return;
      driveFetch_('https://www.googleapis.com/drive/v3/files/' + fid + '/permissions/' + p.id + '?supportsAllDrives=true', { method: 'delete' });
      r.移除.push(e);
    });
    rep[label] = r;
  });
  return rep;
}
/** 系統維護：立即同步檔案資料夾共用 */
function apiShareSync(args, user) { const r = shareSync_(); log_(user.Email, '同步檔案共用', '', r); return r; }
/** 改善檔案移到另一案件（對應錯誤時用）：args = {fileId, caseId} */
function apiImpMove(args, user) {
  const lock = LockService.getScriptLock(); lock.waitLock(30000);
  try {
    const f = findRows_('紀錄檔', '檔案ID', String(args.fileId || '')).find(x => x.種類 === IMP_KIND);
    if (!f) throw new Error('找不到改善檔案');
    const c = findRows_('案件', '案件編號', String(args.caseId || ''))[0];
    if (!c) throw new Error('找不到案件 ' + args.caseId);
    const from = f.案件編號;
    const n = findRows_('紀錄檔', '案件編號', c.案件編號).filter(x => x.種類 === IMP_KIND).length;
    const ext = (String(f.檔名).match(/\.[A-Za-z0-9]{2,5}$/) || [''])[0];
    const base = recFileName_(c, 'x' + ext).replace(/_(督導|查核)紀錄_/, '_' + IMP_KIND + '_');
    const name = n ? base.replace(/(\.[A-Za-z0-9]{2,5})?$/, m => '_' + (n + 1) + m) : base;
    driveFetch_('https://www.googleapis.com/drive/v3/files/' + f.檔案ID + '?supportsAllDrives=true', { method: 'patch', contentType: 'application/json', payload: JSON.stringify({ name: name }) });
    f.案件編號 = c.案件編號; f.檔名 = name; writeRow_('紀錄檔', f);
    const src = readTable_('改善來源').find(r => String(r.系統檔案ID) === String(f.檔案ID));
    if (src) { src.案件編號 = c.案件編號; src.說明 = name + '（由 ' + from + ' 改對應）'; src.處理時間 = nowStr_(); writeRow_('改善來源', src); }
    log_(user.Email, '改善檔案改對應', c.案件編號, { 原案件: from, 檔名: name });
    return { ok: true, name: name, from: from };
  } finally { lock.releaseLock(); }
}
  // 尚未辦理（日期在今天之後）的案件不會有改善檔案，不列入對應
  const today = ymd_(new Date());
  const all = readTable_('案件').filter(c => c.狀態 !== ST_CANCEL && c.狀態 !== ST_VOID && !(c.日期 && c.日期 > today)), cases = all.filter(c => c.日期);
  shareSync: [apiShareSync, ['系統維護']],
  impMove: [apiImpMove, ['行程編輯']],
    try { shareSync_(); } catch (e) { log_(user.Email, '同步檔案共用失敗', '', { 錯誤: e.message }); }
